        "A hash of the object as it shipped. The object still hashing to this value is what shipped and untouched means.": "Een hash van het object zoals het is meegeleverd. Dat het object nog steeds naar deze waarde hasht, is wat meegeleverd en onaangeroerd betekent.",
        "A JSON expression that derives this answer from other fields, evaluated by OpenRegister. A Twig expression is not accepted: the JSON form is diffable and an auditor can read it a year later, which is the decision this field carries.": "Een JSON-expressie die dit antwoord afleidt uit andere velden, uitgerekend door OpenRegister. Een Twig-expressie wordt hier niet geaccepteerd: de JSON-vorm is te diffen en een auditor leest hem een jaar later nog, en dat is de keuze die dit veld draagt.",
        "A JSON object with inputs[], outputs[] and rules[]. Each rule row aligns positionally to the inputs and outputs.": "Een JSON-object met inputs[], outputs[] en rules[]. Elke regelrij correspondeert positioneel met de inputs en outputs.",
