        "Cases are not set up yet. Ask your administrator.": "Zaken zijn nog niet ingericht. Vraag het uw beheerder.",
        "Cases are running on this version. Editing it changes them too. Make a new version instead, and the running cases stay on this one.": "Er lopen zaken op deze versie. Als je hem aanpast, verandert er ook iets voor die zaken. Maak een nieuwe versie, dan blijven de lopende zaken op deze staan.",
