        "Cases could not be reached. The next check tries again.": "Zaken waren niet bereikbaar. De volgende controle probeert het opnieuw.",
        "Cases from %1$s: %2$s. Open your case list to see them.": "Zaken van %1$s: %2$s. Open je zakenlijst om ze te zien.",
        "cases near or past deadline": "zaken bij of voorbij deadline",
        "Cases on map": "Zaken op kaart",
        "Cases that belong together without one leading the other, such as the cases one intake submission opens. Symmetric: both sides read \"hangt samen met\". Written by CaseRelationService.": "Zaken die bij elkaar horen zonder dat de ene de andere aanstuurt, zoals de zaken die één intakeformulier opent. Symmetrisch: beide kanten lezen \"hangt samen met\". Geschreven door CaseRelationService.",
        "Cases that follow on from this one. Written by CaseRelationService as the typed half of relevanteAndereZaken; the far side reads it as \"heeft vervolg\" through OpenRegister's /used.": "Zaken die op deze volgen. Geschreven door CaseRelationService als de getypeerde helft van relevanteAndereZaken; de andere kant leest het als \"heeft vervolg\" via /used van OpenRegister.",
        "Cases this one contributes to. Written by CaseRelationService as the typed half of relevanteAndereZaken; the far side reads it as \"krijgt bijdrage van\" through OpenRegister's /used.": "Zaken waaraan deze bijdraagt. Geschreven door CaseRelationService als de getypeerde helft van relevanteAndereZaken; de andere kant leest het als \"krijgt bijdrage van\" via /used van OpenRegister.",
        "Cases this one is about. Written by CaseRelationService as the typed half of relevanteAndereZaken; the far side reads it as \"onderwerp van\" through OpenRegister's /used.": "Zaken waarover deze gaat. Geschreven door CaseRelationService als de getypeerde helft van relevanteAndereZaken; de andere kant leest het als \"onderwerp van\" via /used van OpenRegister.",
        "Cases this one waits on. A vergunning that cannot be decided until a bezwaar is, for instance: when the case it waits on has its term extended or paused, the handler of this case is offered the same move. Written by CaseRelationService as the typed half of relevanteAndereZaken; the far side reads it as \"blokkeert\" through OpenRegister's /used.": "Zaken waar deze zaak op wacht. Bijvoorbeeld een vergunning waarover pas beslist kan worden als een bezwaar is afgedaan: wordt de termijn van de zaak waarop gewacht wordt verlengd of gepauzeerd, dan krijgt de behandelaar van deze zaak dezelfde zet aangeboden. Geschreven door CaseRelationService als de getypeerde helft van relevanteAndereZaken; de andere kant leest het via /used van OpenRegister als \"blokkeert\".",
