        "CMMN case-file event on the referenced case-file item that satisfies this sentry: 'set' when the item first receives a value, 'changed' on any subsequent update.": "CMMN-gebeurtenis op het genoemde case-file-item die aan deze sentry voldoet: 'set' zodra het item voor het eerst een waarde krijgt, 'changed' bij elke volgende wijziging.",
        "CMMN plan-item type: 'stage' nests other plan items in a sub-plan, 'humanTask' is completed by a case worker, 'milestone' marks a point-in-time achievement with no work of its own.": "Soort CMMN-planitem: 'stage' nest andere planitems in een subplan, 'humanTask' wordt door een behandelaar afgerond en 'milestone' markeert een bereikt punt zonder eigen werk.",
        "CMMN runtime plan-item state, holding planItemStates, milestones, caseFile and eventLog. Only the case model engine writes it. It is present when the case type's handlingModel is 'cmmn', and empty for cases handled by BPMN.": "Runtimetoestand van het CMMN-plan, met planItemStates, milestones, caseFile en eventLog. Alleen de zaakmodelengine schrijft erin. Het veld is er wanneer het handlingModel van het zaaktype 'cmmn' is, en leeg voor zaken die met BPMN worden afgehandeld.",
        "CMMN standard event on the referenced plan item that satisfies this sentry: 'complete' when it reaches Completed, 'terminate' when it reaches Terminated, 'disable' when it reaches Disabled.": "Standaard CMMN-gebeurtenis op het genoemde planitem die aan deze sentry voldoet: 'complete' zodra het Completed bereikt, 'terminate' bij Terminated en 'disable' bij Disabled.",
