        "Configure AI features for document classification, data extraction, Q&A, summarization, routing and decision support": "Configureer AI-functies voor documentclassificatie, gegevensextractie, Q&A, samenvatting, routering en besluitondersteuning",
        "Configure case types": "Zaaktypen configureren",
        "Configure case types in Dossiq admin settings": "Configureer zaaktypen in de Dossiq-beheerinstellingen",
        "Configure DMN-style decision tables (inputs, outputs, rules and a hit policy) that domain experts can maintain without a developer. A workflow step can invoke a decision by key, and decisions are also evaluable via the REST API.": "Configureer DMN-beslistabellen (inputs, outputs, regels en een hit policy) die domeinexperts zonder ontwikkelaar kunnen beheren. Een workflowstap kan een beslissing op sleutel aanroepen, en beslissingen zijn ook te evalueren via de REST-API.",
        "Configure GIS map layers for case location views (WMS, WFS, PDOK)": "Configureer GIS-kaartlagen voor zaaklocatieweergaven (WMS, WFS, PDOK)",
        "Configure how the KCC-werkplek bridge identifies burgers, opens the case-voorblad, scores sentiment, and routes calls. DigiD authentication and the telephony screen-pop are delivered by Integriq and pipelinq respectively; only the Dossiq-side behaviour is configured here.": "Stel in hoe de KCC-werkplekbrug burgers identificeert, het zaak-voorblad opent, sentiment scoort en gesprekken routeert. DigiD-authenticatie en de telefonie-screen-pop worden geleverd door respectievelijk Integriq en pipelinq; hier wordt alleen het Dossiq-gedeelte geconfigureerd.",
        "Configure mandate decisions, organisational roles, role assignments, and import legacy mandate exports": "Configureer mandaatbesluiten, organisatierollen, roltoewijzingen en importeer oude mandaatexports",
        "Configure mandate decisions, organisational roles, role assignments, and import legacy mandate exports. All changes are version-tracked.": "Configureer mandaatbesluiten, organisatierollen, roltoewijzingen en importeer oude mandaatexports. Alle wijzigingen worden per versie bijgehouden.",
        "Configure property mappings between English OpenRegister fields and Dutch ZGW API fields": "Configureer eigenschapstoewijzingen tussen Engelse OpenRegister-velden en Nederlandse ZGW-API-velden",
        "Configure retention periods per zaaktype. Cases reaching their retention threshold trigger e-Depot handover; permanent retention skips archive submission.": "Configureer bewaartermijnen per zaaktype. Zaken die hun bewaardrempel bereiken activeren een e-Depot-overdracht; permanente bewaring slaat archiefaanlevering over.",
        "Configure reusable inspection checklists for VTH cases (Toezicht). Checklists are versioned and linked to case types.": "Configureer herbruikbare inspectiechecklists voor VTH-zaken (Toezicht). Checklists worden per versie bijgehouden en gekoppeld aan zaaktypen.",
        "Configure reusable inspection checklists per case type. Checklists are versioned. Active inspections always use the version they started with.": "Configureer herbruikbare inspectiechecklists per zaaktype. Checklists worden per versie bijgehouden. Actieve inspecties gebruiken altijd de versie waarmee ze zijn begonnen.",
        "Configure statutory term definitions per zaaktype (legal basis, duration, validity). Saving a new version automatically sets validFrom=tomorrow on the new version and validUntil=today on the prior version. New cases use the latest version; running cases keep the version they were bound to.": "Configureer wettelijke termijndefinities per zaaktype (wettelijke grondslag, duur, geldigheid). Bij het opslaan van een nieuwe versie wordt automatisch validFrom=morgen ingesteld op de nieuwe versie en validUntil=vandaag op de vorige versie. Nieuwe zaken gebruiken de nieuwste versie; lopende zaken behouden de versie waaraan ze gebonden waren.",
        "Configure statutory term definitions per zaaktype for AWB termijnbewaking (legal basis, duration, validity). Versioning is enforced on save.": "Configureer wettelijke termijndefinities per zaaktype voor AWB-termijnbewaking (wettelijke grondslag, duur, geldigheid). Versiebeheer wordt afgedwongen bij opslaan.",
        "Configure the Landelijke Handhavingsstrategie matrix. Each cell defines the intervention for a combination of severity (ernst) and behavior (gedrag).": "Configureer de matrix van de Landelijke Handhavingsstrategie. Elke cel definieert de interventie voor een combinatie van ernst en gedrag.",
        "Configure the shared functional mailbox (e.g. zaken@gemeente.nl) that the inbound poller ingests and auto-links to cases by [ZAAK-YYYY-NNNNNN] subject tag. Outbound mail and per-user accounts are owned by Nextcloud Mail. They are not configured here.": "Configureer de gedeelde functionele mailbox (bijv. zaken@gemeente.nl) die de inkomende poller inleest en automatisch aan zaken koppelt via de onderwerptag [ZAAK-YYYY-NNNNNN]. Uitgaande e-mail en accounts per gebruiker vallen onder Nextcloud Mail. Die worden hier niet geconfigureerd.",
        "Configure the shared functional mailbox (e.g. zaken@gemeente.nl) that the inbound poller ingests and auto-links to cases by [ZAAK-YYYY-NNNNNN] subject tag. Per-user mail accounts stay in Nextcloud Mail. The outbound fields below cover only the mail dossiq sends itself. That is workflow actions and the case email screen.": "Configureer de gedeelde functionele mailbox (bijv. zaken@gemeente.nl) die de inkomende poller inleest en automatisch aan zaken koppelt via de onderwerptag [ZAAK-YYYY-NNNNNN]. Mailaccounts per gebruiker blijven in Nextcloud Mail. De uitgaande velden hieronder gelden alleen voor de e-mail die dossiq zelf verstuurt. Dat zijn workflowacties en het e-mailscherm bij de zaak.",
        "Configure the shared secret used to validate ERP payment-confirmation callbacks for dwangsom (penalty payment) uitbetalingen.": "Configureer het gedeelde geheim waarmee ERP-betalingsbevestigingscallbacks voor dwangsomuitbetalingen worden gevalideerd.",
        "Configure the shared secret used to validate the X-Procest-Signature HMAC-SHA256 header on the public dwangsom payment-confirmation callback ({endpoint}). Without a configured secret, every callback request is rejected (HTTP 401). An unconfigured secret is never treated as an implicit pass.": "Configureer het gedeelde geheim waarmee de X-Procest-Signature HMAC-SHA256-header op de openbare dwangsom-betalingsbevestigingscallback ({endpoint}) wordt gevalideerd. Zonder geconfigureerd geheim wordt elk callbackverzoek geweigerd (HTTP 401). Een niet-geconfigureerd geheim wordt nooit als een impliciete goedkeuring behandeld.",
        "Configure which consultations are mandatory or optional for each case type.": "Configureer welke consultaties verplicht of optioneel zijn voor elk zaaktype.",
