        "Each thing the applicant has to send, as its own row. A list rather than a sentence, because only a list lets the answer say WHICH of them arrived, and a partly answered request is the ordinary case.": "Elk ding dat de aanvrager moet opsturen, als eigen rij. Een lijst in plaats van een zin, want alleen een lijst laat het antwoord zeggen WELKE ervan binnenkwamen, en een deels beantwoord verzoek is het gewone geval.",
        "Each user still switches it on for their own mailbox. Until then, nothing is linked.": "Elke gebruiker zet dit zelf aan voor de eigen mailbox. Tot die tijd wordt niets gekoppeld.",
