        "Event": "Gebeurtenis",
        "Event date": "Datum van de gebeurtenis",
        "Event Deadline Reminder": "Gebeurtenis: herinnering aan een termijn",
        "Event Document Added": "Gebeurtenis: document toegevoegd",
        "Event kind": "Soort gebeurtenis",
        "Event kind. This fragment adds the two a chasing pause produces: `chased` for a reminder that went out, and `chase-escalated` for the silence after the last one. A fragment list is CONCATENATED onto the base list, so the values declared in 60-termijnbewaking.json all stand.": "Soort gebeurtenis. Dit fragment voegt de twee toe die een pauze met herinneringen oplevert: `chased` voor een verstuurde herinnering, en `chase-escalated` voor de stilte na de laatste. Een fragmentlijst wordt ACHTER de basislijst geplakt, dus de waarden uit 60-termijnbewaking.json blijven allemaal staan.",
        "Event Message From Handler": "Gebeurtenis: bericht van de behandelaar",
        "Event Status Change": "Gebeurtenis: statuswijziging",
        "Event that must occur: either {planItem, standardEvent} or {caseFileItem, caseFileEvent}.": "Gebeurtenis die moet plaatsvinden: of {planItem, standardEvent}, of {caseFileItem, caseFileEvent}.",
        "Event timestamp (immutable)": "Tijdstip van de gebeurtenis (onveranderlijk)",
        "Event Type": "Soort gebeurtenis",
        "Event-specific data payload as a JSON-serialisable object": "Gegevens bij de gebeurtenis, als object dat naar JSON geschreven kan worden",
        "Events": "Gebeurtenissen",
        "Every case follows a case type, its blueprint. The case type decides the statuses a case moves through, how long it may take, who handles it and what may be decided. Have a look; you do not need to make one, 88 ship with the app.": "Elke zaak volgt een zaaktype, de blauwdruk. Het zaaktype bepaalt welke statussen een zaak doorloopt, hoe lang die mag duren, wie hem behandelt en wat er besloten mag worden. Kijk gerust rond; u hoeft er geen te maken, er zijn er 88 meegeleverd.",
        "Every case type, status, result and role dossiq seeded, and whether you changed it since. A newer shipped version is offered per object and never overwrites a change you made.": "Elk zaaktype, elke status, elk resultaat en elke rol die dossiq plaatste, en of u die sindsdien veranderde. Een nieuwere meegeleverde versie wordt per object aangeboden en overschrijft nooit een wijziging van u.",
        "Every conversation you start from this case lands here. You see when it was held, who joined and how long it lasted.": "Elk gesprek dat je vanuit deze zaak start, komt hier te staan. Je ziet wanneer het plaatsvond, wie meededen en hoe lang het duurde.",
        "Every half year": "Elk halfjaar",
        "Every item becomes a task on the case when it enters this status. A required item holds the case here until its task is done.": "Elk punt wordt een taak op de zaak zodra de zaak deze status krijgt. Een verplicht punt houdt de zaak hier tot die taak af is.",
        "Every kind": "Alle soorten",
        "Every message the intake mailbox processed. You see the filter that decided and what the sender checks found. A message that became no case says why.": "Elk bericht dat de intakemailbox heeft verwerkt. Je ziet welk filter besliste en wat de afzendercontroles vonden. Een bericht dat geen zaak werd, vertelt waarom.",
        "Every month": "Elke maand",
        "Every outcome": "Elke uitkomst",
        "Every quarter": "Elk kwartaal",
        "Every raising and every clearing this case has had, oldest first. A case flagged once is a case with a problem; a case flagged four times by four people is a different case, and the difference is only readable because no earlier reason was overwritten.": "Elke keer dat deze zaak is gevlagd en weer is vrijgegeven, oudste eerst. Een zaak die één keer is gevlagd is een zaak met een probleem; een zaak die vier keer door vier mensen is gevlagd is een andere zaak, en dat verschil is alleen leesbaar omdat geen eerdere reden is overschreven.",
        "Every report Dossiq offers, in one place. Pick a report to open it.": "Elke rapportage die Dossiq biedt, op één plek. Kies een rapportage om die te openen.",
        "Every review: who, when, and what changed": "Elke herziening: wie, wanneer en wat er veranderde",
        "Every setting says who decided it. A setting your team made is one you can still change for yourself.": "Bij elke instelling staat wie die heeft gezet. Wat je team instelt, kun je zelf nog aanpassen.",
        "Every system here is a municipal case system or a workflow engine, and the list is drawn from what they do, in the shape we do it. A capability none of them has is missing from the list, not from the market. A product that splits the work differently scores low without being worse, and that bias runs in our favour. We add rows as we read more systems, so a lower score in a later release can mean the list grew rather than the product shrank.": "Elk systeem hier is een gemeentelijk zaaksysteem of een workflow-engine, en de lijst komt voort uit wat die systemen doen, in de vorm waarin wij het doen. Functionaliteit die geen van hen heeft, ontbreekt in de lijst en niet in de markt. Een product dat het werk anders verdeelt, scoort laag zonder slechter te zijn, en die vertekening valt in ons voordeel uit. We voegen rijen toe naarmate we meer systemen lezen, dus een lager cijfer in een latere release kan betekenen dat de lijst groeide en niet dat het product kromp.",
        "Every year": "Elk jaar",
        "Everyone": "Iedereen",
        "Everything the platform checks when a case is saved, in the order it checks it. Statuses and fields are declared on the other tabs; this is what came of them.": "Alles wat het platform controleert bij het opslaan van een zaak, in de volgorde waarin het dat doet. Statussen en velden legt u op de andere tabbladen vast; dit is wat daaruit volgde.",
