        "Extra properties this case answers, as decided by its case type. Each entry holds the definition it answers, that definition's name, and the value. Cases of different types carry different entries here, and a case whose type declares none carries an empty array.": "Extra eigenschappen die deze zaak beantwoordt, bepaald door het zaaktype. Elke regel bevat de definitie die beantwoord wordt, de naam van die definitie en de waarde. Zaken van verschillende typen bevatten hier dus verschillende regels, en een zaak waarvan het type er geen declareert bevat een lege lijst.",
