        "Hard limit value (NULL = unlimited). Only for cases_per_month and active_users: the limits for storage_gb and api_calls_per_hour live on the Organisation, as storageQuota and requestQuota, and are read from there": "Harde bovengrens (leeg betekent onbeperkt). Alleen voor cases_per_month en active_users: de grenzen voor storage_gb en api_calls_per_hour staan op de Organisatie, als storageQuota en requestQuota, en worden daar gelezen",
