        "Lifecycle state of this definition. Authoritative going forward; isDraft/isActive remain for backwards compatibility. draft = editable, cannot back new cases. published = immutable, can back new cases (one active per caseType). deprecated = immutable, cannot back new cases, existing cases keep using it.": "Levensloopstatus van deze definitie. Vanaf nu leidend; isDraft en isActive blijven bestaan voor compatibiliteit. draft betekent bewerkbaar en niet bruikbaar onder nieuwe zaken. published betekent onveranderlijk en bruikbaar onder nieuwe zaken (één actieve per zaaktype). deprecated betekent onveranderlijk en niet bruikbaar onder nieuwe zaken; bestaande zaken blijven hem gebruiken.",
        "Lifecycle state. inadmissible represents the terminal advice that the bezwaar is inadmissible (Awb Art. 7:13(7))": "Levensloopstatus. inadmissible staat voor het eindadvies dat het bezwaar niet-ontvankelijk is (Awb art. 7:13 lid 7)",
