        "List addresses, or whole domains written as @voorbeeld.nl. A blocked sender opens no case by mail. They can still mail a colleague. The allow half of this list is Nextcloud Mail’s trusted senders.": "Noteer adressen, of hele domeinen geschreven als @voorbeeld.nl. Een geblokkeerde afzender opent geen zaak per mail. Diegene kan nog steeds een collega mailen. De toestaanhelft van deze lijst zijn de vertrouwde afzenders van Nextcloud Mail.",
