        "Live conversation": "Live gesprek",
        "Live conversations held on this case, one object per conversation: kind (conversation|majorChannel), subject, roomId, roomUrl, startedAt, startedBy, participants, durationSeconds and endedAt. Written by CaseConversationService so the archive sees a call that only Talk would otherwise remember. What a conversation produced is filed separately as a case document, under the case type's visibility declaration.": "Levende gesprekken die op deze zaak zijn gevoerd, één object per gesprek: kind (conversation|majorChannel), subject, roomId, roomUrl, startedAt, startedBy, participants, durationSeconds en endedAt. Geschreven door CaseConversationService, zodat het archief een gesprek ziet dat anders alleen Talk zou onthouden. Wat een gesprek opleverde wordt apart als zaakdocument vastgelegd, onder de zichtbaarheidsverklaring van het zaaktype.",
