        "Nextcloud group ID for department-based consultation assignment": "Nextcloud-groeps-id waarmee adviesvragen op afdeling worden toegewezen",
        "Nextcloud group ID that holds this role. OpenRegister RBAC uses this as the canonical role identifier (ADR-022): at workflow-publish time dossiq resolves each step/transition's assignee role to this group id and writes the literal id into the transition authorization list, so OR enforces step access server-side via IGroupManager. IGroupManager::groupExists() must return true for the value. Null = role not yet mapped to a group (open to all authenticated users).": "Nextcloud-groeps-id dat deze rol draagt. De RBAC van OpenRegister gebruikt dit als de canonieke rolidentificatie (ADR-022): bij het publiceren van een workflow zoekt dossiq voor elke stap of overgang de rol van de toegewezene op tot dit groeps-id en schrijft het letterlijk in de autorisatielijst van de overgang, zodat OpenRegister de toegang tot de stap op de server afdwingt via IGroupManager. IGroupManager::groupExists() moet voor deze waarde waar teruggeven. Leeg betekent dat de rol nog niet aan een groep hangt en dus openstaat voor elke ingelogde gebruiker.",
        "Nextcloud group that holds this role. OpenRegister uses it to enforce who may perform this role's workflow steps. Must be an existing Nextcloud group ID; leave empty for no group restriction.": "Nextcloud-groep die deze rol bevat. OpenRegister gebruikt deze om af te dwingen wie de workflowstappen van deze rol mag uitvoeren. Moet een bestaande Nextcloud-groep-ID zijn; laat leeg voor geen groepsbeperking.",
