        "Off": "Uit",
        "Off by default. Tick it to put this contact on the timeline the applicant reads.": "Staat standaard uit. Vink het aan om dit contact op de tijdlijn te zetten die de aanvrager leest.",
        "Off for the team": "Uit voor het team",
        "Off leaves the declaration in place and stops it gating anything, so a gate can be lifted without losing what it said.": "Uit laat de verklaring staan en zorgt dat die niets meer tegenhoudt, zodat een poort open kan zonder dat je kwijtraakt wat hij zei.",
        "Off only where no remedy is open against these decisions. Publication says nothing about a case type that declares this off, and warns about one that simply left the declaration empty.": "Alleen uit wanneer er tegen deze besluiten geen rechtsmiddel openstaat. Publicatie zegt niets over een zaaktype dat dit uitdrukkelijk uit zet, en waarschuwt bij een zaaktype dat de verklaring gewoon leeg liet.",
        "Off only where the law does not ask for one. Turning it off warns on publication and names Awb 4:3a.": "Uit alleen waar de wet er niet om vraagt. Uitzetten waarschuwt bij publicatie en noemt Awb 4:3a.",
        "Off stops the marker being raised, without removing what it was for.": "Uit laat de markering niet zetten, zonder weg te halen waar hij voor was.",
        "Off stops this destination opening a case, without removing what it was for.": "Uit opent deze bestemming geen zaak meer, zonder dat verdwijnt waar zij voor was.",
        "Off stops this moment sending, without removing what it was for.": "Uit laat dit moment niets versturen, zonder weg te halen waar het voor was.",
