        "One choice per line": "Één keuze per regel",
        "One expression string per input, positionally aligned to inputs[]": "Eén expressie per invoer, op positie afgestemd op inputs[]",
        "One line naming what this request is about, so a list of requests reads without opening each one.": "Eén regel die noemt waar dit verzoek over gaat, zodat een lijst met verzoeken leesbaar is zonder ze stuk voor stuk te openen.",
        "One literal value per output, positionally aligned to outputs[]": "Eén letterlijke waarde per uitvoer, op positie afgestemd op outputs[]",
        "One message a day naming what is waiting on you. Nothing waiting means no message.": "Eén bericht per dag met wat er op je wacht. Wacht er niets, dan komt er geen bericht.",
        "One message the intake mailbox processed, with its original, its authentication results, the filter that decided and what became of it.": "Een bericht dat de intakemailbox heeft verwerkt, met het origineel, de authenticatieresultaten, het filter dat besliste en wat ermee is gebeurd.",
        "One of the field filters was refused, so this list is not an answer.": "Een van de veldfilters is geweigerd, dus deze lijst is geen antwoord.",
        "One row per item a split moved off this case: what it was, where it went and when. `CaseSplitPlan::forSelection()` produces these and until now the schema had nowhere to store them. Written rather than derived, because the item itself no longer names this case once it has moved, so nothing could reconstruct what left.": "Eén regel per item dat een splitsing van deze zaak heeft weggehaald: wat het was, waar het heen ging en wanneer. `CaseSplitPlan::forSelection()` maakt ze, en tot nu toe had het schema geen plek om ze te bewaren. Geschreven in plaats van afgeleid, want het item zelf noemt deze zaak niet meer zodra het weg is, dus niets kon reconstrueren wat er is vertrokken.",
        "One sentence saying why. The access tab shows it beside the field, so a handler who cannot see something reads the rule instead of guessing. OpenRegister returns it as the refusal message when the rule stops a save.": "Eén zin die zegt waarom. Het tabblad Toegang toont hem naast het veld, zodat een behandelaar die iets niet kan zien de regel leest in plaats van te gissen. OpenRegister geeft hem terug als weigeringsbericht wanneer de regel een opslag tegenhoudt.",
        "One term for the whole chain of phases, in working days, split over the phases by the share each declares. A phase that overruns shrinks the phases after it. The chain end never moves, so a chain whose phases have eaten it reports zero days left rather than a later date.": "Een termijn voor de hele keten van fasen, in werkdagen, verdeeld over de fasen volgens het aandeel dat elke fase vastlegt. Een fase die uitloopt verkleint de fasen erna. Het einde van de keten verschuift nooit, dus een keten waarvan de fasen hem hebben opgegeten meldt nul dagen in plaats van een latere datum.",
        "One-time token used to activate this supplier user account": "Eenmalig token om dit leveranciersaccount te activeren",
        "Online form (formulier)": "Onlineformulier (formulier)",
        "Only a closed case can be reopened.": "Alleen een afgesloten zaak kan worden heropend.",
        "Only a handler of this case sees who follows it": "Alleen een behandelaar van deze zaak ziet wie haar volgt",
        "Only an administrator can read the rules of a case.": "Alleen een beheerder kan de regels van een zaak lezen.",
        "Only for these groups": "Alleen voor deze groepen",
        "Only in some cases": "Alleen in sommige zaken",
        "Only in {areas}": "Alleen in {areas}",
        "Only published case types can be set as default": "Alleen gepubliceerde zaaktypen kunnen als standaard worden ingesteld",
        "Only somebody who may open this case sees who has held it": "Alleen wie deze zaak mag openen, ziet wie hem heeft gehad",
        "Only the fields you select below are shared. Never the whole case. The remote organisation gets read-only access to a snapshot; it can collaborate via the activity stream but cannot change the case.": "Alleen de hieronder geselecteerde velden worden gedeeld. Nooit de volledige zaak. De externe organisatie krijgt alleen-lezen toegang tot een momentopname; zij kan samenwerken via het activiteitenoverzicht maar kan de zaak niet wijzigen.",
        "Only the latest active version surfaces in the picker": "Alleen de nieuwste actieve versie verschijnt in de kiezer",
        "Only the subject and the start of each message are read. A case number further down is missed.": "Alleen het onderwerp en het begin van elk bericht worden gelezen. Een zaaknummer verderop wordt gemist.",
        "Only the subject and the start of each message are read. Only cases you work on are linked.": "Alleen het onderwerp en het begin van elk bericht worden gelezen. Alleen zaken waaraan u werkt worden gekoppeld.",
        "Only this group and administrators read the intake log. Only they release a held message. The log keeps the original of every message the mailbox received. Leave it empty and only administrators can read it.": "Alleen deze groep en beheerders lezen het intakelogboek. Alleen zij geven een vastgehouden bericht vrij. Het logboek bewaart het origineel van elk bericht dat de mailbox ontving. Laat het leeg en alleen beheerders kunnen het lezen.",
        "Only used when responseType is getal or meting": "Alleen gebruikt wanneer responseType getal of meting is",
        "Only what I can do unilaterally": "Alleen wat ik eenzijdig kan doen",
