        "Produces the per-subject processing extract from OpenRegister (AVG art. 15). The export itself is logged.": "Stelt het verwerkingsuittreksel per betrokkene op vanuit OpenRegister (AVG art. 15). De export zelf wordt gelogd.",
        "Product": "Product",
        "Product ID": "Product-ID",
        "productenOfDiensten contains a value not present in the zaaktype.": "productenOfDiensten bevat een waarde die niet in het zaaktype voorkomt.",
        "Products or Services": "Producten of diensten",
        "Products/services (fees) that apply to this case type. An entry is either a Pipelinq product uuid (ADR-003), where the charge on a concrete case is a Pipelinq financial transaction, or the product URL a ZGW client sent as productenOfDiensten. The items constraint was format uuid, which made the ZTC zaaktypen endpoint refuse every conformant ZGW body, since that field is a list of URLs.": "Producten of diensten (leges) die bij dit zaaktype horen. Een regel is of een product-uuid uit Pipelinq (ADR-003), waarbij de kosten op een concrete zaak een financiële transactie in Pipelinq zijn, of de product-URL die een ZGW-client als productenOfDiensten stuurde. De beperking op items was format uuid, waardoor het zaaktypen-endpoint van de ZTC elke ZGW-body weigerde die zich aan de standaard hield, want dat veld is een lijst met URL's.",
