        "Protected from erasure": "Beschermd tegen wissen",
        "Provenance back-link (ADR-048/ADR-051) to the originating object that was handed off into this case (e.g. a Pipelinq request), carrying the contract `source` field. Empty for manually-created cases; the chain source→case is also navigable via OpenRegister's handoff provenance relations.": "Herkomstverwijzing (ADR-048 en ADR-051) naar het object dat aan deze zaak is overgedragen (bijvoorbeeld een verzoek uit Pipelinq), met het contractveld `source`. Leeg bij zaken die met de hand zijn gemaakt; de keten van bron naar zaak is ook te volgen via de herkomstrelaties van OpenRegister.",
        "Provenance marker: identifies the row as official fictitious test data and names its fixture source.": "Herkomstmerk: het merkt de regel als officiële fictieve testgegevens en noemt de fixture waar die vandaan komt.",
        "Provenance of this location (bag = validated against BAG; pdok-reverse = reverse-geocoded; gps = field capture; free = manual; geocoded = forward-geocoded; import = CSV importer)": "Herkomst van deze locatie (bag = gecontroleerd tegen de BAG; pdok-reverse = omgekeerd gegeocodeerd; gps = in het veld vastgelegd; free = handmatig; geocoded = vooruit gegeocodeerd; import = uit de CSV-import)",
        "Provide an explanation for your advice...": "Geef een toelichting op uw advies...",
