        "Proxy Enabled": "Proxy aan",
        "Pseudonymous portal reference of the EXTERNAL field inspector this checklist run is assigned to (ADR-046 inspector audience). Distinct from `inspector` (internal NC user UID): external inspectors have no Nextcloud account, so Portaliq scopes their runs by this server-stamped subject reference. Empty for internally-handled runs.": "Pseudonieme portaalverwijzing naar de EXTERNE inspecteur aan wie deze checklistronde is toegewezen (inspecteurspubliek uit ADR-046). Iets anders dan `inspector` (de interne Nextcloud-gebruikers-uid): externe inspecteurs hebben geen Nextcloud-account, dus bakent Portaliq hun ronden af met deze door de server gezette verwijzing naar de betrokkene. Leeg bij ronden die intern worden afgehandeld.",
        "Pseudonymous portal reference of the EXTERNAL field inspector this report is assigned to (ADR-046 inspector audience). Distinct from `inspector` (internal NC user UID): external inspectors have no Nextcloud account, so Portaliq scopes their reports by this server-stamped subject reference. Empty for internally-handled inspections.": "Pseudonieme portaalverwijzing naar de EXTERNE inspecteur aan wie dit rapport is toegewezen (inspecteurspubliek uit ADR-046). Iets anders dan `inspector` (de interne Nextcloud-gebruikers-uid): externe inspecteurs hebben geen Nextcloud-account, dus bakent Portaliq hun rapporten af met deze door de server gezette verwijzing naar de betrokkene. Leeg bij inspecties die intern worden afgehandeld.",
        "Pseudonymous subject reference (never raw BSN). One preference record per subject.": "Pseudonieme verwijzing naar de betrokkene (nooit een onbewerkt BSN). Eén voorkeursregel per betrokkene.",
        "Pseudonymous subject reference of the sender (BSN/KvK hash), never the raw BSN. Used for IDOR scoping.": "Pseudonieme verwijzing naar de afzender (een hash van het BSN of KvK-nummer), nooit het onbewerkte BSN. Gebruikt om IDOR af te bakenen.",
        "Pseudonymous subject reference of the submitter (never raw BSN). Used for IDOR scoping.": "Pseudonieme verwijzing naar de indiener (nooit een onbewerkt BSN). Gebruikt om IDOR af te bakenen.",
        "Pseudonymous, one-way subject reference (never a raw BSN/KvK) of the citizen this case belongs to in the external Portaliq portal (ADR-046 citizen audience). Server-stamped from the authenticated portal identity; the sole IDOR-safe scope key for a citizen's 'Mijn gemeente' cases. Empty for cases with no external citizen owner.": "Pseudonieme eenrichtingsverwijzing (nooit een onbewerkt BSN of KvK-nummer) naar de burger van wie deze zaak is in het externe Portaliq-portaal (burgerpubliek uit ADR-046). Door de server gezet vanuit de ingelogde portaalidentiteit; de enige IDOR-veilige sleutel om de zaken in 'Mijn gemeente' van een burger af te bakenen. Leeg bij zaken zonder externe burger als eigenaar.",
