        "Reference to the complaint category": "Verwijzing naar de categorie van de klacht",
        "Reference to the current status type. The case type sets the first one, through the x-openregister-prefill block on caseType. Moves between statuses belong to dossiq's StatusTransitionService. Every case type carries its own workflow template, so the routes are data rather than schema. OpenRegister reads them through the provider this schema's x-openregister-lifecycle block names. So available-actions answers a case's real transitions. The write path validates against that same reader. x-relation-filter scopes the picker to the case type's own statuses.": "Verwijzing naar het huidige statustype. Het zaaktype zet de eerste, via het blok x-openregister-prefill op caseType. Het verzetten tussen statussen hoort bij StatusTransitionService van dossiq. Elk zaaktype draagt zijn eigen workflowsjabloon, dus de routes zijn gegevens en geen schema. OpenRegister leest ze via de provider die het blok x-openregister-lifecycle in dit schema noemt. Zo beantwoordt available-actions de echte overgangen van een zaak. Het schrijfpad valideert tegen diezelfde lezer. x-relation-filter beperkt de kiezer tot de statussen van het zaaktype zelf.",
