        "This could not be read: {reason}": "Dit konden we niet lezen: {reason}",
        "This dialog was opened without a case.": "Dit venster is geopend zonder zaak.",
        "This did not work. Try again.": "Dit lukte niet. Probeer het opnieuw.",
        "This document has no pending chunked upload.": "Dit document heeft geen openstaande chunked upload.",
        "This evidence document is linked to a settlement and is immutable": "Dit bewijsstuk is gekoppeld aan een vaststelling en is onveranderlijk",
        "This export expired. Ask for it again.": "Dit export is verlopen. Vraag het opnieuw aan.",
        "This field": "Dit veld",
        "This field cannot be shown here.": "Dit veld kan hier niet getoond worden.",
        "This field has the type {type}, which this instance does not offer. dossiq keeps it as it is.": "Dit veld heeft het type {type}, dat deze installatie niet aanbiedt. Dossiq laat het staan zoals het is.",
        "This field names a concept scheme and carries its own list. The scheme wins and the typed choices are ignored.": "Dit veld noemt een begrippenlijst en draagt een eigen lijst. De begrippenlijst wint en de getypte keuzes worden genegeerd.",
        "This file could not be read as a message.": "Dit bestand is niet als bericht te lezen.",
        "This file has no document record yet; saving creates one.": "Dit bestand heeft nog geen documentregistratie; opslaan maakt er een aan.",
        "This file is not on a case.": "Dit bestand staat niet op een zaak.",
        "This goes on your own calendar and on your queue. It is not a case.": "Dit komt op je eigen agenda en in je wachtrij. Het is geen zaak.",
        "This instance keeps the setting here rather than with your other notifications.": "Deze omgeving bewaart de instelling hier en niet bij je andere meldingen.",
        "This instance routes no dossiq notifications yet.": "Deze omgeving routeert nog geen dossiq-meldingen.",
        "this instance runs": "deze instantie draait",
        "This is not a saved mail file, so there is no message in it to read.": "Dit is geen opgeslagen mailbestand, dus er zit geen bericht in om te lezen.",
        "This is recorded against {user}.": "Dit wordt vastgelegd op naam van {user}.",
        "This letter was not sent, and no reason was given.": "Deze brief is niet verstuurd en er is geen reden gegeven.",
        "This message was blocked by your organisation's AI guardrail policy.": "Dit bericht is geblokkeerd door het AI-guardrailbeleid van uw organisatie.",
        "This moves the case to a final status.": "Hiermee gaat de zaak naar een eindstatus.",
        "This panel was opened without a file, so there is nothing to read versions of.": "Dit paneel is geopend zonder bestand, dus er zijn geen versies om te lezen.",
        "This pattern cannot find case numbers. Check that it is valid and has a capture group.": "Met dit patroon worden geen zaaknummers gevonden. Controleer of het geldig is en een vanggroep heeft.",
        "This phase only. It never moves the case term.": "Alleen deze fase. Het verschuift de zaaktermijn nooit.",
        "This phase's share of the chain term, as a percentage. Use it when the case type declares one term for the whole chain and you want it split over the phases. The shares of the phases after an overrunning one are recomputed, and the chain end stays where it was.": "Het aandeel van deze fase in de ketentermijn, als percentage. Gebruik dit als het zaaktype een termijn voor de hele keten vastlegt en je die over de fasen wilt verdelen. De aandelen van de fasen na een uitgelopen fase worden herberekend, en het einde van de keten blijft waar het was.",
        "This plan has no goals yet": "Dit plan heeft nog geen doelen",
        "This plan was due for review on {date}. A plan that is not revisited stops describing the household it is about.": "Dit plan moest op {date} herzien worden. Een plan dat niet opnieuw bekeken wordt, beschrijft op een gegeven moment niet meer het gezin waar het over gaat.",
        "This proposal has been returned. Adjust the document and resubmit it.": "Dit voorstel is teruggestuurd. Pas het document aan en dien het opnieuw in.",
