        "Track a tenant through the seven onboarding steps, run the go-live readiness check and activate the tenant. One-time setup, so it belongs here rather than in the daily navigation.": "Volg een tenant door de zeven onboardingstappen, voer de go-live-gereedheidscontrole uit en activeer de tenant. Eenmalige inrichting, dus dit hoort hier en niet in de dagelijkse navigatie.",
