        "True = an optional item the case worker may choose to enable. False = mandatory, auto-cascades to active once entry criteria are met.": "Waar betekent een optioneel item dat de behandelaar kan aanzetten. Onwaar betekent verplicht, en het gaat vanzelf naar actief zodra aan de instapvoorwaarden is voldaan.",
        "True when the plafond has been hit; no further accrual": "Waar zodra het plafond is bereikt; er komt niets meer bij",
        "True when the request arrived when the municipality was closed, so the clock started later than the moment the applicant pressed send. Derivable from the two moments and stored anyway, because it is what a report filters on and what the ontvangstbevestiging branches on. Absent, rather than false, on a case the working calendar could not place: an unanswered calendar does not know whether the week was open.": "Waar wanneer het verzoek binnenkwam terwijl de gemeente dicht was, zodat de klok later begon dan het moment waarop de aanvrager op verzenden drukte. Af te leiden uit de twee momenten en toch opgeslagen, want het is waar een rapport op filtert en waar de ontvangstbevestiging op vertakt. Afwezig, en niet onwaar, bij een zaak die de werkkalender niet kon plaatsen: een kalender die geen antwoord geeft, weet niet of de week open was.",
        "True when the transition was admin free-form on a caseType without an active workflowTemplate": "Waar wanneer de overgang een vrije beheerdersovergang was op een caseType zonder actief workflowTemplate",
        "True when vastgesteldBedrag < totaal voorschotten": "Waar wanneer vastgesteldBedrag lager is dan het totaal aan voorschotten",
